<?php
session_start();
require_once __DIR__.'/../config/config.php';
$type=in_array($_GET['type']??'', ['publisher','shop','user'], true)?$_GET['type']:'publisher';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);
if(!$id){http_response_code(404);exit('ไม่พบข้อมูลผู้ขาย');}
$isShop=$type==='shop';$isUser=$type==='user';
if($isUser){$table='users';$idCol='user_id';$nameCol='display_name';}
elseif($isShop){$table='shops';$idCol='shop_id';$nameCol='shop_name';}
else{$table='publishers';$idCol='publisher_id';$nameCol='company_name';}
$stmt=$pdo->prepare("SELECT * FROM $table WHERE $idCol=?");$stmt->execute([$id]);$profile=$stmt->fetch(PDO::FETCH_ASSOC);
if(!$profile){http_response_code(404);exit('ไม่พบข้อมูลผู้ขาย');}
$name=$isUser?($profile[$nameCol]?:$profile['email']):wanawanSellerName($profile[$nameCol],$type);
$fallback=$isShop?'ร้านหนังสือบนวนวรรณ พื้นที่ส่งต่อเรื่องราวและหนังสือดี ๆ ให้แก่นักอ่าน':($isUser?'สมาชิกวนวรรณ ผู้ส่งต่อหนังสือและเรื่องราวดี ๆ':'สำนักพิมพ์พันธมิตรของวนวรรณ คัดสรรผลงานคุณภาพสำหรับนักอ่าน');
$description=($isUser?($profile['bio']??''):($profile['description']??''))?:$fallback;

// Get the most recent province used by this seller
$sellerProvince = '';
if ($isUser) {
    $provStmt = $pdo->prepare("
        (SELECT seller_province as prov, created_at FROM books WHERE seller_type='user' AND seller_id=? AND seller_province IS NOT NULL AND seller_province != '')
        UNION ALL
        (SELECT owner_province as prov, created_at FROM exchanges WHERE owner_id=? AND owner_province IS NOT NULL AND owner_province != '')
        ORDER BY created_at DESC LIMIT 1
    ");
    $provStmt->execute([$id, $id]);
    $sellerProvince = $provStmt->fetchColumn() ?: '';
} else {
    $provStmt = $pdo->prepare("SELECT seller_province as prov FROM books WHERE seller_type=? AND seller_id=? AND seller_province IS NOT NULL AND seller_province != '' ORDER BY created_at DESC LIMIT 1");
    $provStmt->execute([$type, $id]);
    $sellerProvince = $provStmt->fetchColumn() ?: '';
}

$followers=(int)($profile['followers_count']??0);
$tab=($_GET['tab']??'latest')==='all'?'all':'latest';$page=max(1,(int)($_GET['page']??1));$perPage=12;$offset=($page-1)*$perPage;
$count=$pdo->prepare("SELECT COUNT(*) FROM books WHERE seller_type=? AND seller_id=? AND status='available'");$count->execute([$type,$id]);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));
$ratingStmt=$pdo->prepare("SELECT COALESCE(AVG(r.rating),0),COUNT(r.review_id) FROM books b LEFT JOIN book_reviews r ON r.book_id=b.book_id WHERE b.seller_type=? AND b.seller_id=?");$ratingStmt->execute([$type,$id]);[$sellerRating,$sellerReviewCount]=$ratingStmt->fetch(PDO::FETCH_NUM)?:[0,0];
$booksStmt=$pdo->prepare("SELECT * FROM books WHERE seller_type=? AND seller_id=? AND status='available' ORDER BY created_at DESC,book_id DESC LIMIT $perPage OFFSET $offset");$booksStmt->execute([$type,$id]);$books=$booksStmt->fetchAll(PDO::FETCH_ASSOC);
$publisherPosts=[];if(in_array($type,['publisher','shop'],true)){try{$postTable=$type==='shop'?'shop_posts':'publisher_posts';$postOwner=$type==='shop'?'shop_id':'publisher_id';$postStmt=$pdo->prepare("SELECT p.* FROM $postTable p LEFT JOIN seller_promotions sp ON sp.promotion_id=p.promotion_id WHERE p.$postOwner=? AND (p.promotion_id IS NULL OR (sp.is_active=1 AND sp.starts_at<=NOW() AND sp.ends_at>=NOW())) ORDER BY p.created_at DESC,p.post_id DESC LIMIT 10");$postStmt->execute([$id]);$publisherPosts=$postStmt->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){}}
function pdImage(?string $v):?string{if(!$v)return null;if(preg_match('#^https?://#i',$v))return $v;$v=ltrim(str_replace('\\','/',$v),'/');if(str_starts_with($v,'pages/'))return'/'.$v;if(str_starts_with($v,'uploads/')){if(is_file(__DIR__.'/../'.$v))return'/'.$v;return'/pages/'.$v;}if(str_starts_with($v,'assets/'))return'/'.$v;return'/assets/image/'.$v;}
function pdBookImage(?string $v):?string{if(!$v)return null;if(preg_match('#^https?://#i',$v))return$v;$v=ltrim(str_replace('\\','/',$v),'/');if(str_starts_with($v,'uploads/')){if(is_file(__DIR__.'/../'.$v))return'/'.$v;return'/pages/'.$v;}return str_starts_with($v,'assets/')?'/'.$v:'/assets/image/books/'.$v;}
$profileVerified=in_array($type,['publisher','shop'],true);
$profileSourceLabel=match($type){'publisher'=>'สำนักพิมพ์','shop'=>'ร้านหนังสือ',default=>'ผู้ขายทั่วไป'};
$profileSourceClass=in_array($type,['publisher','shop','user'],true)?$type:'user';
ob_start(function(string $html) use($profileSourceLabel,$profileSourceClass,$profileVerified,$publisherPosts,$type,$id,$sellerRating,$sellerReviewCount):string{
    $verifiedClass=$profileVerified?' is-verified':'';
    $tag='<span class="profile-source-tag profile-source-tag--'.htmlspecialchars($profileSourceClass).$verifiedClass.'">'.htmlspecialchars($profileSourceLabel).'</span>';
    $style='<style>.profile-name{display:inline-block;vertical-align:middle}.profile-source-tag{display:inline-flex;align-items:center;gap:5px;margin:7px 0 8px 10px;padding:5px 10px;border-radius:6px;font-size:11px;font-weight:700;vertical-align:middle;white-space:nowrap}.profile-source-tag.is-verified::before{content:"✓";width:14px;height:14px;border-radius:50%;display:grid;place-items:center;color:#fff;font-size:9px}.profile-source-tag--publisher{background:#f9dce7;border:1px solid #edbfd0;color:#a14468}.profile-source-tag--publisher.is-verified::before{background:#c65f86}.profile-source-tag--shop{background:#dff2f3;border:1px solid #b9dde0;color:#176272}.profile-source-tag--shop.is-verified::before{background:#268091}.profile-source-tag--user{background:#f2eeee;border:1px solid #e1d9dc;color:#756a6e}@media(max-width:600px){.profile-source-tag{margin-left:6px}}</style>';
    $html=preg_replace('#(<h1 class="profile-name">.*?</h1>)#s','$1'.$tag.$style,$html,1)??$html;
    $ratingStat='<div class="profile-stat"><strong>★ '.number_format((float)$sellerRating,1).'</strong><span>'.number_format((int)$sellerReviewCount).' รีวิว</span></div>';
    $html=str_replace('</div></div><div class="profile-actions">',$ratingStat.'</div></div><div class="profile-actions">',$html);
    $reviewButton='<a class="profile-btn profile-reviews" style="display:inline-flex;align-items:center;justify-content:center;gap:7px;text-decoration:none;background:#fff9fb;color:#b75e7f;border-color:#edbfd0" href="/pages/seller_reviews.php?type='.rawurlencode($type).'&amp;id='.(int)$id.'"><span aria-hidden="true">★</span> ดูรีวิวร้าน</a>';
    $html=str_replace('<div class="profile-actions">','<div class="profile-actions">'.$reviewButton,$html);
    $postStyles=array_map(fn($post)=>['background'=>$post['background_color']??'#FFFFFF','bold'=>!empty($post['is_bold']),'italic'=>!empty($post['is_italic'])],$publisherPosts);
    $script='<script>document.addEventListener("DOMContentLoaded",()=>{const styles='.json_encode($postStyles,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).';document.querySelectorAll(".announcement-list .announcement-card:not(.is-carousel-clone)").forEach((card,index)=>{const s=styles[index]||{};card.style.background=s.background||"#FFFFFF";const body=card.querySelector(".announcement-body p");if(body){body.style.fontWeight=s.bold?"700":"400";body.style.fontStyle=s.italic?"italic":"normal";}});});</script>';
    if($type==='shop')$html=str_replace(['ประกาศจากสำนักพิมพ์','aria-label="ประกาศจากสำนักพิมพ์"'],['ประกาศจากร้านหนังสือ','aria-label="ประกาศจากร้านหนังสือ"'],$html);
    return str_replace('</body>',$script.'</body>',$html);
});
$breadcrumbs = [['label' => $name, 'url' => '']];
?>
<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($name)?> - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css?v=<?= filemtime(__DIR__.'/../assets/css/styles.css') ?>"><style>
