eat(4,1fr);gap:20px}.empty{grid-column:1/-1;text-align:center;padding:70px;color:var(--text-muted)}.pagination{display:flex;justify-content:center;gap:10px;margin-top:50px}.pagination a{width:44px;height:44px;border:1px solid var(--secondary-color);border-radius:8px;display:grid;place-items:center;text-decoration:none;color:var(--secondary-color)}.pagination .active{background:var(--secondary-color);color:#fff}@media(max-width:900px){.profile-hero{grid-template-columns:120px 1fr}.profile-image{width:110px;height:110px}.profile-actions{grid-column:2}.profile-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.profile-wrap{padding:30px 18px 60px}.profile-hero{grid-template-columns:1fr;text-align:center}.profile-image{margin:auto}.profile-actions{grid-column:auto;justify-content:center}.profile-stats{justify-content:center}.publisher-posts,.profile-grid{grid-template-columns:repeat(2, 1fr)}.book-tabs{justify-content:center}.book-tabs a{min-width:130px}}
</style></head><body><?php require __DIR__.'/../components/header.php';?><main class="profile-wrap"><section class="profile-hero"><div class="profile-image"><?php if($img=pdImage($profile['profile_image']??null)):?><img src="<?=htmlspecialchars($img)?>" alt="<?=htmlspecialchars($name)?>"><?php else:?><?=htmlspecialchars(mb_substr($name,0,1))?><?php endif;?></div><div><h1 class="profile-name"><?=htmlspecialchars($name)?></h1><p class="profile-desc"><?=nl2br(htmlspecialchars($description))?></p><?php if($sellerProvince):?><p style="color:var(--text-muted);margin:8px 0 0;font-size:14px;display:flex;align-items:center;gap:4px;"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="var(--primary-color)" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg> <?=htmlspecialchars($sellerProvince)?></p><?php endif;?><div class="profile-stats"><div class="profile-stat"><strong data-followers-type="<?=htmlspecialchars($type)?>" data-followers-id="<?=$id?>"><?=number_format($followers)?></strong><span>ผู้ติดตาม</span></div><div class="profile-stat"><strong><?=number_format($total)?></strong><span>หนังสือทั้งหมด</span></div></div></div><div class="profile-actions"><?php $follow_type=$type;$follow_id=$id;$follow_class='profile-btn follow';require __DIR__.'/../components/follow_button.php';?><a class="profile-btn message" style="display:grid;place-items:center;text-decoration:none" href="/pages/chat.php?seller_type=<?=urlencode($type)?>&amp;seller_id=<?=$id?>&amp;t=<?=time()?>">ข้อความ</a></div></section>
<?php if($publisherPosts):?><style>.announcement-strip{margin:-18px 0 44px;padding:22px;border:1px solid #ead6dd;border-radius:18px;background:linear-gradient(135deg,#fff8fa,#fff)}.announcement-head{display:flex;align-items:center;gap:9px;margin-bottom:15px}.announcement-head h2{margin:0;color:var(--secondary-color);font-size:22px}.announcement-icon{width:24px;height:24px;color:#d37799}.announcement-list{display:flex;gap:15px;overflow-x:auto;padding:2px 2px 10px;scroll-snap-type:x mandatory;scrollbar-color:#db9db4 transparent}.announcement-card{flex:0 0 min(520px,86vw);min-height:150px;display:grid;grid-template-columns:190px 1fr;border:1px solid #ecdde2;border-radius:14px;overflow:hidden;background:#fff;scroll-snap-align:start;box-shadow:0 5px 16px #75465812}.announcement-card.text-only{display:block;padding:22px;background:linear-gradient(135deg,#f9e4eb,#fff7f9)}.announcement-image{width:100%;height:100%;min-height:170px;object-fit:contain;background:#f8f2ef}.announcement-body{padding:19px}.announcement-label{display:inline-block;padding:4px 10px;border-radius:16px;background:#f6dce5;color:#ac5475;font-size:12px;font-weight:700;margin-bottom:8px}.announcement-body p{white-space:pre-wrap;line-height:1.65;margin:4px 0 14px;color:#4e4549}.announcement-body time{font-size:12px;color:#93858a}@media(max-width:600px){.announcement-strip{padding:16px}.announcement-card{grid-template-columns:1fr;flex-basis:88vw}.announcement-image{height:190px}.announcement-body{padding:16px}}</style><section class="announcement-strip" aria-label="ประกาศจากสำนักพิมพ์"><div class="announcement-head"><svg class="announcement-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 5 6 9H2v6h4l5 4V5z"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07"/></svg><h2>ประกาศจากสำนักพิมพ์</h2></div><div class="announcement-list"><?php foreach($publisherPosts as $post):$postImage=pdImage($post['image_url']??null);?><article class="announcement-card <?=$postImage?'has-image':'text-only'?>"><?php if($postImage):?><img class="announcement-image" src="<?=htmlspecialchars($postImage)?>" alt="รูปประกอบประกาศ"><?php endif;?><div class="announcement-body"><span class="announcement-label">ประกาศ</span><?php if($post['content']!==''):?><p><?=htmlspecialchars($post['content'])?></p><?php endif;?><time><?=date('d/m/Y H:i',strtotime($post['created_at']))?></time></div></article><?php endforeach;?></div></section><?php endif;?>
<h2 class="section-title">หนังสือของร้าน</h2><nav class="book-tabs"><a class="<?=$tab==='latest'?'active':''?>" href="?type=<?=$type?>&amp;id=<?=$id?>&amp;tab=latest">ใหม่ล่าสุด</a><a class="<?=$tab==='all'?'active':''?>" href="?type=<?=$type?>&amp;id=<?=$id?>&amp;tab=all">ทั้งหมด</a></nav><div class="profile-grid"><?php if(!$books):?><p class="empty">ยังไม่มีหนังสือที่พร้อมจำหน่าย</p><?php else:foreach($books as $r){$book=['id'=>$r['book_id'],'title'=>$r['title'],'author'=>$r['author']??'','price'=>$r['price'],'badge'=>'มาใหม่','image'=>pdBookImage($r['image_cover']??null),'stock_quantity'=>$r['stock_quantity']??1];$card_type=($r['book_type']??'used')==='new'?'new':'used';require __DIR__.'/../components/book_card.php';}endif;?></div><?php if($pages>1):?><nav class="pagination"><?php for($p=1;$p<=$pages;$p++):?><a class="<?=$p===$page?'active':''?>" href="?type=<?=$type?>&amp;id=<?=$id?>&amp;tab=<?=$tab?>&amp;page=<?=$p?>"><?=$p?></a><?php endfor;?></nav><?php endif;?></main><?php require __DIR__.'/../components/footer.php';?><script>function addToCart(id){alert('เพิ่มหนังสือลงรถเข็นแล้ว')}</script></body></html>
